<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';require_once __DIR__.'/../services/TicketService.php';Auth::requireLogin();$user=Auth::user();$id=(int)($_GET['id']??$_POST['id']??0);$ticket=TicketService::find($id);if(!$ticket){http_response_code(404);exit('تیکت در دسترس نیست.');}if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');if(($_POST['action']??'reply')==='manage')TicketService::manage($id,$_POST,(int)$user['id']);else{$messageId=TicketService::reply($id,(string)($_POST['message']??''),(int)$user['id'],isset($_POST['is_internal']));if(($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$saved=Upload::save($_FILES['attachment'],'uploads/tickets',['pdf','doc','docx','xls','xlsx','jpg','jpeg','png','webp','txt','zip'],10*1024*1024);if(!$saved['ok'])throw new InvalidArgumentException($saved['error']);TicketService::addAttachment($id,$messageId,(int)$user['id'],$saved);}}flash('تغییرات تیکت ثبت شد.');}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Ticket view: '.$e->getMessage());flash('عملیات تیکت انجام نشد.','danger');}redirect('/employee/ticket-view.php?id='.$id);}$users=TicketService::canManage()?Database::fetchAll('SELECT id,name FROM users WHERE status="active" ORDER BY name'):[];$units=TicketService::canManage()?Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY sort_order,title'):[];$pageTitle='تیکت '.$ticket['ticket_no'];require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><small><?=e($ticket['ticket_no'])?></small><h1><?=e($ticket['subject'])?></h1><p class="muted"><?=e($ticket['category_title'])?> · <?=e(TicketService::STATUSES[$ticket['status']]??$ticket['status'])?></p></div><a class="btn" href="<?=TicketService::canManage()?'/admin/tickets.php':'/employee/tickets.php'?>">بازگشت</a></div>
<section class="grid grid-2"><main><?php foreach($ticket['messages'] as $message):?><article class="card"><header><strong><?=e($message['user_name'])?></strong><small><?=e(format_jalali_datetime($message['created_at']))?></small><?php if($message['is_internal']):?><span class="badge">یادداشت داخلی</span><?php endif?></header><p><?=nl2br(e($message['message']))?></p></article><?php endforeach?><section class="card admin-form"><h2>پاسخ جدید</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><textarea name="message" rows="5" required></textarea><input type="file" name="attachment" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.webp,.txt,.zip"><?php if(TicketService::canManage()):?><label><input type="checkbox" name="is_internal"> یادداشت داخلی</label><?php endif?><button class="btn btn-primary">ارسال پاسخ</button></form></section></main><aside><section class="card"><h2>جزئیات</h2><p>درخواست‌کننده: <?=e($ticket['requester_name'])?></p><p>مسئول: <?=e($ticket['assignee_name']?:'تخصیص نیافته')?></p><p>مهلت: <?=e($ticket['due_at']?format_jalali_datetime($ticket['due_at']):'تعیین نشده')?></p><?php foreach($ticket['attachments'] as $file):?><p>پیوست: <a href="/employee/ticket-attachment.php?id=<?=(int)$file['id']?>"><?=e($file['original_name'])?></a></p><?php endforeach?></section><?php if(TicketService::canManage()):?><section class="card admin-form"><h2>مدیریت تیکت</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="manage"><input type="hidden" name="id" value="<?=$id?>"><label>وضعیت<select name="status"><?php foreach(TicketService::STATUSES as $key=>$label):?><option value="<?=$key?>" <?=$ticket['status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label>مسئول<select name="assigned_user_id"><option value="">بدون مسئول</option><?php foreach($users as $item):?><option value="<?=$item['id']?>" <?=(int)$ticket['assigned_user_id']===$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach?></select></label><label>واحد<select name="assigned_unit_id"><option value="">بدون واحد</option><?php foreach($units as $item):?><option value="<?=$item['id']?>" <?=(int)$ticket['assigned_unit_id']===$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label>مهلت<input type="datetime-local" name="due_at" value="<?=e($ticket['due_at']?str_replace(' ','T',substr($ticket['due_at'],0,16)):'')?>"></label><label>یادداشت تغییر<textarea name="note"></textarea></label><button class="btn">ذخیره</button></form></section><?php endif?></aside></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
